contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address adr, bytes memory data, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(adr != address(c));

        uint ownerBalBefore = address(this).balance;

        c.Command{value: amount}(adr, data); if (__ESBMC_reverted()) return;

        uint ownerBalAfter = address(this).balance;

        assert(ownerBalAfter <= ownerBalBefore);
    }
}

